608	func TestSelectAddressReplacementKeepsRotation(t *testing.T) {
609		// One instance keeps its id but gets a new address: the registration bumps
610		// once, that instance resets to unknown/0 while untouched instances keep
611		// their observations, and the rotation continues after the last chosen id
612		// instead of restarting at the smallest id.
613		input := `{"requests":[
614			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
615			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":11,"healthy":true},
616			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":12,"healthy":true},
617			{"type":"health","service":"svc","instanceId":"c","expectedRevision":1,"sequence":13,"healthy":true},
618			{"type":"health","service":"svc","instanceId":"d","expectedRevision":1,"sequence":14,"healthy":false,"reason":"connection refused"},
619			{"type":"select","service":"svc","expectedRevision":1},
620			{"type":"select","service":"svc","expectedRevision":1},
621			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"},{"id":"c","address":"h3:3"},{"id":"d","address":"h4:4"}]},
622			{"type":"select","service":"svc","expectedRevision":2},
623			{"type":"select","service":"svc","expectedRevision":2}
624		]}`
625		out, code := runRegisterWith(t, input)
626		if code != 0 {
627			t.Fatalf("exit code: %d, output: %s", code, out)
628		}
629		var got registerOutput
630		if err := json.Unmarshal([]byte(out), &got); err != nil {
631			t.Fatalf("output is not JSON: %v\n%s", err, out)
632		}
633		if len(got.Results) != 10 {
634			t.Fatalf("results: %+v", got.Results)
635		}
636		// Rotation before the replacement: a then b, cursor rests on b.
637		if r := got.Results[5]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 11 {
638			t.Fatalf("first select: %+v", r)
639		}
640		if r := got.Results[6]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 {
641			t.Fatalf("second select: %+v", r)
642		}
643		// The address-only replacement succeeds and bumps the revision exactly once.
644		if r := got.Results[7]; !r.OK || !r.Changed || r.Revision != 2 {
645			t.Fatalf("address replacement: %+v", r)
646		}
647		// The new address of a has no observation yet, so it is skipped; the
648		// rotation continues just after b and lands on c, never on a's old address.
649		if r := got.Results[8]; !r.OK || r.InstanceID != "c" || r.Address != "h3:3" || r.Sequence != 13 || r.Revision != 2 {
650			t.Fatalf("select after replacement should continue after b at c: %+v", r)
651		}
652		// Past the end the rotation wraps to the smallest eligible id (b), proving
653		// it did not restart from the smallest id because of the replacement.
654		if r := got.Results[9]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 12 || r.Revision != 2 {
655			t.Fatalf("select should wrap to smallest eligible id: %+v", r)
656		}
657		// Final state: a is unknown at sequence 0 with no leftover reason; the
658		// untouched instances keep their health, sequence and reason.
659		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
660			t.Fatalf("services: %+v", got.Services)
661		}
662		insts := got.Services[0].Instances
663		if len(insts) != 4 {
664			t.Fatalf("instances: %+v", insts)
665		}
666		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "unknown" || insts[0].Sequence != 0 || insts[0].Reason != "" {
667			t.Fatalf("replaced instance should reset to unknown/0: %+v", insts[0])
668		}
669		if insts[1].ID != "b" || insts[1].Health != "healthy" || insts[1].Sequence != 12 {
670			t.Fatalf("b should keep its observation: %+v", insts[1])
671		}
672		if insts[2].ID != "c" || insts[2].Health != "healthy" || insts[2].Sequence != 13 {
673			t.Fatalf("c should keep its observation: %+v", insts[2])
674		}
675		if insts[3].ID != "d" || insts[3].Health != "unhealthy" || insts[3].Sequence != 14 || insts[3].Reason != "connection refused" {
676			t.Fatalf("d should keep its observation and reason: %+v", insts[3])
677		}
678	}
