680	func TestSelectAddressReplacementNoHealthyThenRecovery(t *testing.T) {
681		// Replacing the only healthy instance's address leaves no healthy target:
682		// select reports no_healthy without moving the cursor, a health report
683		// against the old revision conflicts without healing the new address, and
684		// a fresh observation at the current revision (sequence only above the
685		// reset 0, not above the old accepted one) makes the new address eligible
686		// again.
687		input := `{"requests":[
688			{"type":"register","service":"svc","expectedRevision":0,"instances":[{"id":"a","address":"h1:1"},{"id":"b","address":"h2:2"}]},
689			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":20,"healthy":true},
690			{"type":"health","service":"svc","instanceId":"b","expectedRevision":1,"sequence":21,"healthy":false,"reason":"down"},
691			{"type":"select","service":"svc","expectedRevision":1},
692			{"type":"register","service":"svc","expectedRevision":1,"instances":[{"id":"a","address":"h9:9"},{"id":"b","address":"h2:2"}]},
693			{"type":"select","service":"svc","expectedRevision":2},
694			{"type":"health","service":"svc","instanceId":"a","expectedRevision":1,"sequence":99,"healthy":true},
695			{"type":"select","service":"svc","expectedRevision":2},
696			{"type":"health","service":"svc","instanceId":"a","expectedRevision":2,"sequence":1,"healthy":true},
697			{"type":"health","service":"svc","instanceId":"b","expectedRevision":2,"sequence":22,"healthy":true},
698			{"type":"select","service":"svc","expectedRevision":2},
699			{"type":"select","service":"svc","expectedRevision":2}
700		]}`
701		out, code := runRegisterWith(t, input)
702		if code != 1 {
703			t.Fatalf("exit code: %d, output: %s", code, out)
704		}
705		var got registerOutput
706		if err := json.Unmarshal([]byte(out), &got); err != nil {
707			t.Fatalf("output is not JSON: %v\n%s", err, out)
708		}
709		if len(got.Results) != 12 {
710			t.Fatalf("results: %+v", got.Results)
711		}
712		// Cursor rests on a before the replacement.
713		if r := got.Results[3]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 20 {
714			t.Fatalf("select before replacement: %+v", r)
715		}
716		if r := got.Results[4]; !r.OK || !r.Changed || r.Revision != 2 {
717			t.Fatalf("address replacement: %+v", r)
718		}
719		// No healthy instance remains: no_healthy states the reason and the current
720		// revision and fabricates neither an instance id nor an address.
721		if r := got.Results[5]; r.OK || r.Error != "no_healthy" || r.Reason == "" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
722			t.Fatalf("no_healthy after replacement: %+v", r)
723		}
724		// A health report against the old revision conflicts even though its
725		// sequence (99) exceeds the old accepted one (20); it names both revisions.
726		if r := got.Results[6]; r.OK || r.Error != "conflict" || r.Reason == "" || r.ExpectedRevision != 1 || r.ActualRevision != 2 || r.Revision != 2 {
727			t.Fatalf("stale-revision health report: %+v", r)
728		}
729		// The conflicting report did not heal the new address: still no_healthy.
730		if r := got.Results[7]; r.OK || r.Error != "no_healthy" || r.Revision != 2 || r.InstanceID != "" || r.Address != "" {
731			t.Fatalf("new address must not regain eligibility from old revision: %+v", r)
732		}
733		// At the current revision a sequence just above the reset 0 suffices; it
734		// does not need to exceed the 20 accepted for the old address.
735		if r := got.Results[8]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 1 {
736			t.Fatalf("fresh observation at current revision: %+v", r)
737		}
738		if r := got.Results[9]; !r.OK || !r.Changed || r.Revision != 2 || r.Sequence != 22 {
739			t.Fatalf("b recovery: %+v", r)
740		}
741		// The failed selects and health report never moved the cursor off a, so
742		// the rotation continues at b rather than restarting at the smallest id.
743		if r := got.Results[10]; !r.OK || r.InstanceID != "b" || r.Address != "h2:2" || r.Sequence != 22 || r.Revision != 2 {
744			t.Fatalf("rotation should resume after a at b: %+v", r)
745		}
746		// The new address rejoins selection carrying its new address and the new
747		// observation's sequence.
748		if r := got.Results[11]; !r.OK || r.InstanceID != "a" || r.Address != "h9:9" || r.Sequence != 1 || r.Revision != 2 {
749			t.Fatalf("new address should be selected with its new observation: %+v", r)
750		}
751		// The final list reflects only the committed changes.
752		if len(got.Services) != 1 || got.Services[0].Revision != 2 {
753			t.Fatalf("services: %+v", got.Services)
754		}
755		insts := got.Services[0].Instances
756		if len(insts) != 2 {
757			t.Fatalf("instances: %+v", insts)
758		}
759		if insts[0].ID != "a" || insts[0].Address != "h9:9" || insts[0].Health != "healthy" || insts[0].Sequence != 1 || insts[0].Reason != "" {
760			t.Fatalf("a should be healthy at its new address: %+v", insts[0])
761		}
762		if insts[1].ID != "b" || insts[1].Address != "h2:2" || insts[1].Health != "healthy" || insts[1].Sequence != 22 || insts[1].Reason != "" {
763			t.Fatalf("b should be healthy again: %+v", insts[1])
764		}
765	}
