	if r := got.Results[7]; !r.OK || r.InstanceID != "a" || r.Address != "h1:1" || r.Sequence != 5 {
		t.Fatalf("select should wrap to a: %+v", r)
	}
	// The final list shows only the accepted observations; nothing from the
